insert into public.portfolio_items
  (slug, upwork_id, title, role, description, skills, client, video_id, featured, published, sort_order, url)
values
  ($t$shopify-jewelry-store-gtm-meta-capi-and-ga4-offline-and$t$, $t$2070833400382619648$t$, $t$Shopify Jewelry Store: GTM, Meta CAPI & GA4, Offline & Online Tracking$t$, $t$Marketing Analyst$t$, $t$Set up complete online and offline tracking for a German Shopify jewelry brand using GTM, Meta Pixel + CAPI, GA4 Enhanced Ecommerce and Google Ads Enhanced Conversions. Fixed missing and duplicate events, improving data accuracy. The client confirmed the work with a video review.$t$, array[$t$Shopify$t$, $t$Google Tag Manager$t$, $t$Meta Pixel$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$]::text[], $t$Maitea GmbH$t$, $t$VUz-Al0nmz8$t$, true, true, 1, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$lead-attribution-and-crm-automation-gclid-fbclid-and-utm$t$, $t$2030495326716354560$t$, $t$Lead Attribution & CRM Automation: GCLID, FBCLID & UTM Tracking$t$, $t$Marketing Analyst$t$, $t$I solved a critical data gap for a client by building an end-to-end lead attribution pipeline. Previously, they had no visibility into which campaigns drove revenue. Tracking: used GTM to capture GCLID, FBCLID and UTMs. Automation: built n8n and Make workflows to sync leads and attribution data to the CRM instantly. Optimization: set up offline conversion tracking to feed quality data back to Google and Meta Ads. Results: 100% lead source transparency, increased ROAS through data-driven scaling, and a lower CPA by optimizing for qualified leads.$t$, array[$t$Google Tag Manager$t$, $t$Analytics$t$, $t$CRM Automation$t$, $t$Make.com$t$, $t$ClickUp$t$]::text[], null, null, true, true, 2, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$multi-platform-ga4-google-ads-meta-tiktok-snapchat-tracking$t$, $t$2014452576575918080$t$, $t$Multi-Platform (GA4, Google Ads, Meta, TikTok, Snapchat) Tracking Setup$t$, $t$Tracking & Analytics Specialist$t$, $t$Implemented full-funnel tracking for a charity-based ecommerce website built with custom code, using Google Tag Manager (web and server-side). Tracked core events (view_item, add_to_cart, begin_checkout, purchase/donation) across GA4 and Google Ads, Meta (Pixel + CAPI with deduplication), TikTok, Snapchat and X (Twitter). Ensured accurate product and donation values, currency and transaction IDs were passed consistently, and validated events in each platform's test tools to deliver reliable attribution and optimization-ready data.$t$, array[$t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$Pixel Setup & Optimization$t$, $t$Meta Pixel$t$, $t$Server-side GTM$t$]::text[], null, null, true, true, 3, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-and-ga4-purchase-value-tracking$t$, $t$1888309676961374208$t$, $t$Google Ads & GA4 Purchase Value Tracking$t$, $t$Tracking Specialist$t$, $t$Successfully implemented Google Ads and GA4 purchase value tracking for a PrestaShop store using Google Tag Manager. Ensured accurate revenue tracking by dynamically capturing the correct purchase values, improving ad performance and conversion optimization.$t$, array[$t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$Google Ads$t$, $t$Tracking Pixel$t$]::text[], $t$Petr Mai, Profibeauty.cz$t$, $t$-YRJQLpl8rM$t$, false, true, 1004, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$fixing-data-visualization-errors-in-looker-studio$t$, $t$2010355050082652160$t$, $t$Fixing Data Visualization Errors in Looker Studio$t$, $t$Looker Studio Expert$t$, $t$The client reached out with a Looker Studio dashboard that wasn't reflecting real-time data accurately. I performed a full audit of their data connectors and visualization settings to identify the bottlenecks. Resolved "System Error" and "Data Set Configuration" issues, implemented custom SQL and Regex for cleaner data filtering, and updated the visual theme to match the client's brand identity. The client recorded a video testimonial.$t$, array[$t$Looker Studio$t$, $t$Data Visualization$t$, $t$Google Analytics 4$t$, $t$Data Analytics$t$]::text[], null, $t$_uNS2rPx6sI$t$, true, true, 5, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$gclid-capture-and-tracking-integration-for-google-ads$t$, $t$1963111014077186048$t$, $t$GCLID Capture & Tracking Integration for Google Ads$t$, null, $t$I implemented a custom GCLID capture solution to track conversions more accurately from Google Ads. The script stores the Google Click ID (GCLID) whenever a visitor arrives via an ad and preserves it throughout the session, even across multiple pages. At checkout or form submission, the GCLID is passed into the dataLayer or stored in hidden fields for CRM and GA4 tracking. This ensures precise attribution of sales and leads back to campaigns and keywords, helping improve ROAS and campaign optimization.$t$, array[$t$Google Ads$t$, $t$Google Tag Manager$t$, $t$Google Analytics$t$, $t$JavaScript$t$]::text[], null, null, false, true, 1006, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$custom-javascript-tracking-for-funnelish-pricing-tables-ga4$t$, $t$1963092575476400128$t$, $t$Custom JavaScript Tracking for Funnelish Pricing Tables (GA4 + GTM)$t$, null, $t$On a Funnelish website with a complex pricing table, I built a custom JavaScript solution to track user interactions. When a customer clicks "BUY TODAY", the script dynamically captures the exact package name, price per bottle and total price, then pushes this data to the dataLayer for a clean add_to_cart event in GA4. This ensures accurate, reliable tracking and valuable insights where standard tools fall short.$t$, array[$t$Funnelish$t$, $t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$JavaScript$t$]::text[], null, null, false, true, 1007, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$dynamic-price-scraping-with-javascript-for-accurate-revenue$t$, $t$1963090309191774208$t$, $t$Dynamic Price Scraping with JavaScript for Accurate Revenue Tracking$t$, null, $t$I built a JavaScript function to dynamically capture the correct checkout price, even when coupon discounts are applied. The function checks for both the original and "Due Now" prices, returning the accurate value and converting it into a number for analytics. Integrated as a Custom JS Variable in GTM, it ensures precise revenue tracking in GA4, Facebook and other platforms. This solution solves common ecommerce tracking issues with dynamic pricing.$t$, array[$t$Google Tag Manager$t$, $t$JavaScript$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1008, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$facebook-pixel-and-server-side-tracking-and-ga4-tracking$t$, $t$1840879518693933056$t$, $t$Facebook Pixel and Server-Side Tracking, and GA4 Tracking$t$, $t$Marketing Analyst$t$, $t$Implemented advanced tracking for DSPoo.com, enhancing marketing data accuracy and customer insights. Set up and configured Google Tag Manager to manage multiple tracking tags. Implemented GA4 tracking for key user events such as page views, sessions and conversions. Configured custom events in GTM for product views, add-to-cart actions and purchase completions.$t$, array[$t$Facebook Pixel$t$, $t$Google Analytics 4$t$, $t$Meta Pixel$t$, $t$Google Tag Manager$t$]::text[], null, null, false, true, 1009, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$server-side-tracking-using-stape-io$t$, $t$1891949634925838336$t$, $t$Server-Side Tracking Using Stape.io$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Implemented server-side tracking using Stape.io to enhance data accuracy for Google Ads, Meta Pixel, GA4 and other marketing tags. Challenges: bypassing ad blockers, improving data security, keeping page load fast. Solution: configured GTM's server-side container on Stape.io to send cleaner, first-party data to marketing platforms. Impact: improved conversion tracking accuracy, reduced ad costs, better data privacy compliance.$t$, array[$t$Google Tag Manager$t$, $t$Server-side GTM$t$, $t$Stape$t$, $t$Google Analytics 4$t$, $t$Meta Pixel$t$]::text[], null, null, true, true, 10, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$next-js-data-layer-and-gtm-integration-for-advanced-tracking$t$, $t$1917786560337563648$t$, $t$Next.js Data Layer & GTM Integration for Advanced Tracking$t$, $t$Tracking Expert$t$, $t$Developed a custom dataLayer for a Next.js website to enable advanced ecommerce tracking through GTM. Implemented JavaScript event tracking (view item, add to cart, checkout, purchase) integrated with GA4, Google Ads and Meta Pixel. Performance-optimized, modular code validated in GTM Debug Mode. Supports remarketing, conversion tracking and behaviour analytics.$t$, array[$t$Next.js$t$, $t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$JavaScript$t$]::text[], null, null, false, true, 1011, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$hubspot-form-tracking-using-gtm-and-javascript$t$, $t$1917946714478858240$t$, $t$HubSpot Form Tracking using GTM & JavaScript$t$, $t$Tracking Expert$t$, $t$Implemented advanced HubSpot form tracking using custom JavaScript and GTM. Because HubSpot forms load dynamically, I used DOM monitoring and HubSpot submission callbacks to trigger conversion events accurately, and sent submissions to GA4, Google Ads and Meta Pixel with cross-platform attribution.$t$, array[$t$HubSpot$t$, $t$JavaScript$t$, $t$Google Tag Manager$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1012, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$laravel-data-layer-setup-with-javascript-and-gtm-integration$t$, $t$1917785296933507072$t$, $t$Laravel Data Layer Setup with JavaScript & GTM Integration$t$, null, $t$Implemented a custom dataLayer on a Laravel website using JavaScript for enhanced ecommerce tracking via GTM. Integrated product view, add to cart and purchase with GA4, Google Ads and Meta Pixel. Clean, scalable code debugged with GTM Debug Mode and Tag Assistant.$t$, array[$t$JavaScript$t$, $t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$Meta Pixel$t$, $t$Laravel$t$]::text[], null, null, false, true, 1013, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-and-ga4-conversion-tracking-for-squarespace$t$, $t$1917778015244275712$t$, $t$Google Ads & GA4 Conversion Tracking for Squarespace$t$, $t$Tracking Expert$t$, $t$Set up conversion tracking for a Squarespace website using GTM. Integrated GA4 and Google Ads to track form submissions and purchases, verified in GA4 DebugView and Google Ads conversion reports.$t$, array[$t$Squarespace$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$, $t$Google Tag Manager$t$]::text[], null, null, false, true, 1014, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$acuity-scheduling-form-tracking-integration-with-google-ads$t$, $t$1917759067703799808$t$, $t$Acuity Scheduling Form Tracking Integration with Google Ads & GA4$t$, null, $t$Set up conversion tracking for Acuity Scheduling forms using GTM, GA4 and Google Ads. Custom JavaScript detects submissions, fires a GA4 event and a Google Ads conversion. Verified in DebugView and Ads conversion reports. Outcome: accurate lead tracking and better ad performance through improved attribution.$t$, array[$t$JavaScript$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$, $t$Google Tag Manager$t$, $t$Acuity Scheduling$t$]::text[], null, null, false, true, 1015, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$ga4-custom-event-tracking-for-shopify-via-gtm-motherdenim$t$, $t$1915880368918204416$t$, $t$GA4 Custom Event Tracking for Shopify via GTM (motherdenim.com)$t$, $t$Google Analytics 4 Expert$t$, $t$Set up advanced GA4 tracking for collection-page banners and exit gates on motherdenim.com using GTM and JavaScript. Tracked impressions and clicks with parameters for collection name, device, destination, placement, size and type (combined format, e.g. denim-newarrivals-double-1-click), plus slot 1 and slot 2 exit-gate clicks with a clean dataLayer push. Delivered the GTM container (JSON) and full documentation.$t$, array[$t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$JavaScript$t$, $t$Shopify$t$]::text[], null, null, true, true, 16, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$shopify-facebook-pixel-setup-with-conversion-api-via-gtm$t$, $t$1915871468731056128$t$, $t$Shopify Facebook Pixel Setup with Conversion API via GTM$t$, null, $t$Set up Facebook Pixel on a Shopify store using GTM with both browser and server-side (CAPI) tracking. Tracked ViewContent, AddToCart, InitiateCheckout and Purchase, with event matching (email, phone) and testing in Meta Pixel Helper and Events Manager.$t$, array[$t$Shopify$t$, $t$Google Tag Manager$t$, $t$Meta Pixel$t$, $t$CAPI$t$]::text[], null, null, false, true, 1017, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$gravity-forms-tracking-for-google-facebook-and-tiktok-ads$t$, $t$1915865661222240256$t$, $t$Gravity Forms Tracking for Google, Facebook & TikTok Ads$t$, $t$Tracking Expert$t$, $t$Set up Gravity Forms submission tracking on 4 WordPress websites using GTM. Events fire on successful submit and go to Google Ads (conversion), Facebook Pixel (Lead) and TikTok Pixel (SubmitForm), via a gravity_form_submit dataLayer push. Tested in GTM, GA4, Meta and TikTok.$t$, array[$t$Gravity Forms$t$, $t$Google Tag Manager$t$, $t$Meta Pixel$t$, $t$TikTok$t$, $t$Google Ads$t$]::text[], null, null, false, true, 1018, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$twitter-x-pixel-and-conversion-api-setup$t$, $t$1908488194808061952$t$, $t$Twitter (X) Pixel & Conversion API Setup$t$, $t$Web Analyst$t$, $t$Implemented X Pixel and Conversion API for an ecommerce store: pixel via GTM, standard events (Page View, Add to Cart, Purchase), server-side CAPI, event match quality checks and deduplication tested in X Event Manager.$t$, array[$t$Twitter/X$t$, $t$Google Tag Manager$t$, $t$Conversion API$t$]::text[], null, null, false, true, 1019, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-conversion-tracking-for-shopify-store$t$, $t$1908316288601071616$t$, $t$Google Ads Conversion Tracking for Shopify Store$t$, $t$Tracking Expert$t$, $t$Implemented Google Ads conversion tracking on Shopify using Shopify Customer Events and a dataLayer for purchases, add to cart and checkout. Integrated GTM with the store and pushed ecommerce events for granular tracking and campaign optimisation.$t$, array[$t$Shopify$t$, $t$Google Tag Manager$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1020, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-conversion-tracking-for-ecommerce-website$t$, $t$1908314007075401728$t$, $t$Google Ads Conversion Tracking for eCommerce Website$t$, $t$Tracking Expert$t$, $t$Implemented Google Ads conversion tracking for purchases, add to cart and checkout on an ecommerce site via GTM, improving campaign performance and ROAS.$t$, array[$t$Ecommerce$t$, $t$Google Tag Manager$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1021, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-conversion-tracking-for-webflow-website$t$, $t$1908312607603929088$t$, $t$Google Ads Conversion Tracking for Webflow Website$t$, $t$Tracking Expert$t$, $t$Implemented Google Ads conversion tracking on Webflow for form submissions (thank-you page trigger) and CTA button clicks. GTM installed via Webflow custom code, conversion tag and custom triggers configured.$t$, array[$t$Webflow$t$, $t$Google Tag Manager$t$, $t$Google Ads$t$]::text[], null, null, false, true, 1022, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-conversion-tracking-for-wordpress-website$t$, $t$1908310989062578176$t$, $t$Google Ads Conversion Tracking for WordPress Website$t$, $t$Tracking Expert$t$, $t$Implemented Google Ads conversion tracking on WordPress for lead generation: form submissions (Elementor, Gravity Forms, Contact Form 7), call clicks and booking completions, using dataLayer pushes, DOM triggers or thank-you pages depending on the form.$t$, array[$t$Google Tag Manager$t$, $t$WordPress$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1023, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$enhanced-google-ads-lead-tracking-with-gtm$t$, $t$1908309217719697408$t$, $t$Enhanced Google Ads Lead Tracking with GTM$t$, null, $t$Set up precise Google Ads lead conversion tracking for a WordPress service website using Gravity Forms: custom JavaScript pushes an event on successful submission, and a GTM trigger fires only on confirmed submits.$t$, array[$t$Google Tag Manager$t$, $t$Gravity Forms$t$, $t$Google Ads$t$]::text[], null, null, false, true, 1024, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-lead-conversion-tracking-setup-elementor$t$, $t$1908307089030725632$t$, $t$Google Ads Lead Conversion Tracking Setup (Elementor)$t$, $t$Tracking Expert$t$, $t$Implemented Google Ads lead tracking on WordPress with an Elementor form, using GTM form-submission and element-visibility triggers that fire only on successful submits, verified in Google Ads.$t$, array[$t$Lead Generation$t$, $t$Google Ads$t$, $t$Google Tag Manager$t$, $t$Elementor$t$]::text[], null, null, false, true, 1025, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$calendly-conversion-tracking-integration-with-google-ads$t$, $t$1908305752509857792$t$, $t$Calendly Conversion Tracking Integration with Google Ads$t$, $t$Tracking Expert$t$, $t$Tracked completed Calendly bookings as conversions in Google Ads and GA4 via GTM and custom JavaScript, using Calendly's calendly.event_scheduled listener. Verified with Tag Assistant and GA4 DebugView, with consent-based firing for GDPR.$t$, array[$t$Google Ads$t$, $t$Google Tag Manager$t$, $t$Google Analytics 4$t$, $t$Calendly$t$]::text[], null, null, false, true, 1026, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-conversion-tracking-for-a-service-based-website$t$, $t$1908296603153285120$t$, $t$Google Ads Conversion Tracking for a Service-Based Website$t$, $t$Tracking Expert$t$, $t$Complete conversion tracking for a service business on Google Ads: form submits, phone calls and key actions, click-to-call on mobile, verified with Tag Assistant, consent mode configured.$t$, array[$t$Google Tag Manager$t$, $t$Google Ads$t$, $t$Google Analytics 4$t$]::text[], null, null, false, true, 1027, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$google-ads-call-tracking-setup-with-google-tag-manager$t$, $t$1908294466451488768$t$, $t$Google Ads Call Tracking Setup with Google Tag Manager$t$, $t$Tracking Expert$t$, $t$Call tracking for a local service business: Google Ads call conversions via GTM, Google Forwarding Numbers for call extensions, mobile click-to-call events, sent to Google Ads and GA4, consent mode supported.$t$, array[$t$Google Tag Manager$t$, $t$Google Ads$t$, $t$Google Analytics$t$]::text[], null, null, false, true, 1028, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$meta-pixel-and-conversion-api-setup-for-wordpress$t$, $t$1891959390347108352$t$, $t$Meta Pixel & Conversion API Setup for WordPress$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Meta Pixel + CAPI on WordPress. Challenges: data loss from ad blockers and iOS 14+. Solution: Pixel via GTM, CAPI for first-party data, event deduplication. Impact: better tracking, targeting and ROAS.$t$, array[$t$Meta Pixel$t$, $t$Google Tag Manager$t$, $t$CAPI$t$]::text[], null, null, false, true, 1029, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$meta-pixel-and-conversion-api-setup-for-shopify$t$, $t$1891583549473652736$t$, $t$Meta Pixel & Conversion API Setup for Shopify$t$, $t$Web Analytics & Tracking Specialist$t$, $t$Meta Pixel via GTM plus server-side CAPI on Shopify. Events: PageView, ViewContent, AddToCart, InitiateCheckout, Lead, Search, AddPaymentInfo, Purchase, with deduplication.$t$, array[$t$Shopify$t$, $t$Google Tag Manager$t$, $t$Meta Pixel$t$, $t$CAPI$t$]::text[], null, null, false, true, 1030, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$first-party-cookie-capture-for-fbp-fbc-and-gclid$t$, $t$1891968636372860928$t$, $t$First-Party Cookie Capture for FBP, FBC, and GCLID$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Captured and stored FBP, FBC and GCLID in first-party cookies with JavaScript, then sent them to Meta CAPI and Google Ads via GTM for better matching and attribution despite Safari and iOS restrictions.$t$, array[$t$Meta Pixel$t$, $t$Google Ads$t$, $t$Google Tag Manager$t$, $t$JavaScript$t$]::text[], null, null, false, true, 1031, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$meta-pixel-and-conversion-api-setup-for-booking-website$t$, $t$1891967354143793152$t$, $t$Meta Pixel & Conversion API Setup for Booking Website$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Meta Pixel + CAPI on a booking website: page views, bookings and leads; server-side via GTM; deduplication. Impact: better booking tracking, targeting and ROAS.$t$, array[$t$Meta Pixel$t$, $t$Google Tag Manager$t$, $t$CAPI$t$]::text[], null, null, false, true, 1032, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$ga4-custom-report-setup$t$, $t$1891971508879704064$t$, $t$GA4 Custom Report Setup$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Custom GA4 Explore reports with filters and segments for specific user behaviour, plus conversion tracking and attribution configuration.$t$, array[$t$Google Analytics 4$t$, $t$Google Tag Manager$t$, $t$Reporting$t$]::text[], null, null, false, true, 1033, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
  ($t$meta-pixel-and-conversion-api-setup-for-next-js-website$t$, $t$1891965553003859968$t$, $t$Meta Pixel & Conversion API Setup for Next.js Website$t$, $t$Web Analytics Specialist / GTM Expert$t$, $t$Meta Pixel + CAPI on a Next.js website to overcome ad blockers, iOS 14+ and limited client-side tracking. Impact: improved conversion tracking, targeting and ROAS.$t$, array[$t$Next.js$t$, $t$Meta Pixel$t$, $t$Google Tag Manager$t$]::text[], null, null, false, true, 1034, $t$https://www.upwork.com/freelancers/conversiontrackinggtmga4looker$t$),
