-- The Upwork portfolio, in full.
--
-- 20261012000001 created portfolio_items as a title and a link, seeded with
-- nine titles. Sojib then exported the whole portfolio (53 items, 12 Oct 2026)
-- with a description, a role, skills and for some a client and a video. This
-- adds the columns that export needs and replaces the nine rows with all 53.
--
-- What each new column is for:
--
--   slug         the URL: /work/<slug>
--   upwork_id    the item's id on Upwork. Unique, so a re-import updates
--                rather than duplicates.
--   role         "Marketing Analyst". Sojib's own label for his part.
--   description  his own write-up, as exported. Typos fixed, claims untouched.
--   skills       the tags on the card
--   client       only where the client is already named on this site
--   video_id     a YouTube id, for the items with a client video
--   featured     the six that get the larger card
--   images       [{ "src": "/portfolio/<id>/1.webp", "alt": "..." }]. EMPTY for
--                every row: Upwork refuses automated downloads of the
--                screenshots, so they are not here yet. scripts/
--                build-portfolio-images.mjs fills this in once the files have
--                been saved by hand.
--
-- HOW IT WAS APPLIED TO THE LIVE PROJECT. Not as this one file. The 53 rows are
-- 30 kB of text, so on 13 Oct 2026 it went in as two recorded migrations
-- (portfolio_full_columns, portfolio_full_constraints) with the rows loaded in
-- between by a one-off function that the second migration dropped. The end
-- state is identical to running this file, which is the version to use on a
-- fresh database.
--
-- Item 51 (Merchant Center) is not tracking work. It is inserted unpublished,
-- per the note in the export.

alter table public.portfolio_items
  add column slug        text,
  add column upwork_id   text,
  add column role        text,
  add column description text,
  add column skills      text[] not null default '{}',
  add column client      text,
  add column video_id    text,
  add column featured    boolean not null default false,
  add column images      jsonb not null default '[]'::jsonb;

-- The nine seeded rows are a subset of what follows, with nothing pointing at
-- them, so they are replaced rather than matched up by title.
delete from public.portfolio_items;


alter table public.portfolio_items
  alter column slug set not null,
  alter column description set not null,
  add constraint portfolio_items_slug_key unique (slug),
  add constraint portfolio_items_upwork_id_key unique (upwork_id),
  add constraint portfolio_items_slug_shape check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  add constraint portfolio_items_images_is_array check (jsonb_typeof(images) = 'array');

create index portfolio_items_featured_idx on public.portfolio_items (published, featured, sort_order);
